/* load the live hero demo after the page and covers are in, so images come first */
addEventListener("load",()=>setTimeout(()=>{const f=document.getElementById("heroFrame");if(f&&!f.src)f.src=f.dataset.src},600));
const TIERS={signature:"Signature",premium:"Premium",atelier:"Atelier"};
const MANUAL=new Set(["henna-vine","bangles","drum-night","jasmine-veil","jewel-box","rose-window"]);
const OCC={shaadi:"Shaadi",mehndi:"Mehndi",baraat:"Baraat",nikah:"Nikah",walima:"Walima",engagement:"Engagement",muslim:"Muslim Wedding",hindu:"Hindu Wedding",christian:"Christian Wedding",islamic:"Islamic Events",hajj:"Hajj & Umrah",birthday:"Birthday",anniversary:"Anniversary"};const OCC_SEP={muslim:1,islamic:1};const occOf=d=>d.o||"shaadi";const hasOcc=(d,k)=>occOf(d).split(",").includes(k);let occ="all";
DESIGNS.forEach(d=>Object.defineProperty(d,"n",{get(){return cur!=="pkr"?d.en:d.pk}}));
const PRICE={},WAS={};Object.keys(BW_REGION.REGIONS).forEach(c=>{PRICE[c]={};WAS[c]={};["signature","premium","atelier"].forEach(t=>{PRICE[c][t]=BW_REGION.price(t,c);WAS[c][t]=BW_REGION.was(t,c)})});
let cur=BW_REGION.cur;
const reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;

/* marquee */
const mq=document.getElementById("mq");function renderMq(){const names=DESIGNS.map(d=>`<span>${d.n}</span>`).join("");mq.innerHTML=names+names}renderMq();

/* nav */
const nav=document.getElementById("nav"),sheet=document.getElementById("sheet"),burger=document.getElementById("burger");
const onScroll=()=>nav.classList.toggle("solid",scrollY>30);addEventListener("scroll",onScroll,{passive:true});onScroll();
burger.onclick=()=>{const o=!sheet.classList.contains("on");sheet.classList.toggle("on",o);nav.classList.toggle("open",o);burger.setAttribute("aria-expanded",o);document.body.style.overflow=o?"hidden":""};
sheet.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{sheet.classList.remove("on");nav.classList.remove("open");burger.setAttribute("aria-expanded",false);document.body.style.overflow=""}));

/* phone iframe scaling */
function fitPhones(){document.querySelectorAll(".phone").forEach(p=>{const f=p.querySelector("iframe");if(!f)return;if(p.id==="vphone"&&innerWidth<=820){f.style.transform="";return}const w=p.querySelector(".screen").clientWidth;const h=p.querySelector(".screen").clientHeight;f.style.width="390px";f.style.height=(390*h/w)+"px";f.style.transform="scale("+(w/390)+")"})}
addEventListener("resize",fitPhones);fitPhones();

/* filters + grid */
const grid=document.getElementById("grid"),filters=document.getElementById("filters");let filter="all";
const occsEl=document.getElementById("occs");
function occIntoView(el){const b=el&&el.querySelector('[aria-pressed="true"]');if(b&&el.scrollWidth>el.clientWidth)el.scrollTo({left:Math.max(0,b.offsetLeft-el.clientWidth/2+b.offsetWidth/2),behavior:"smooth"})}
function hSwipe(t){if(!t||t.dataset.sw)return;t.dataset.sw=1;let x0=0,y0=0,s0=0,mode=0,lx=0,lt=0,v=0,raf=0;
  const stop=()=>{if(raf){cancelAnimationFrame(raf);raf=0}};
  t.addEventListener("touchstart",e=>{stop();const p=e.touches[0];x0=lx=p.clientX;y0=p.clientY;s0=t.scrollLeft;mode=0;v=0;lt=performance.now();t.style.scrollBehavior="auto"},{passive:true});
  t.addEventListener("touchmove",e=>{const p=e.touches[0],dx=p.clientX-x0,dy=p.clientY-y0;if(!mode&&(Math.abs(dx)>6||Math.abs(dy)>6))mode=Math.abs(dx)>Math.abs(dy)?1:2;
    if(mode===1&&t.scrollWidth>t.clientWidth){e.preventDefault();t.scrollLeft=s0-dx;const now=performance.now(),dt=Math.max(1,now-lt);v=.8*((lx-p.clientX)/dt)+.2*v;lx=p.clientX;lt=now}},{passive:false});
  t.addEventListener("touchend",()=>{const m=mode;mode=0;if(m!==1||performance.now()-lt>80||Math.abs(v)<.05){t.style.scrollBehavior="";return}
    let last=performance.now();const step=now=>{const dt=now-last;last=now;t.scrollLeft+=v*dt;v*=Math.pow(.9965,dt);
      const end=t.scrollLeft<=0||t.scrollLeft>=t.scrollWidth-t.clientWidth-1;if(Math.abs(v)<.02||end){raf=0;t.style.scrollBehavior="";return}raf=requestAnimationFrame(step)};raf=requestAnimationFrame(step)},{passive:true})}
hSwipe(document.getElementById("occs"));hSwipe(document.getElementById("allOccs"));
function renderFilters(){occsEl.innerHTML=occHTML();const opts=tierOpts();if(!opts.some(x=>x[0]===filter))filter="all";
  filters.innerHTML=opts.map(([k,l,n])=>`<button data-f="${k}" aria-pressed="${filter===k}">${l}<span>${n}</span></button>`).join("")}
function cardHTML(d,i,k){return `<article class="design" data-i="${i}">
  <button class="frame" data-pd="${i}" style="background-image:url(${LQ[d.s]||""})" aria-label="See ${d.n}"><img src="img/mock/${d.s}-s.webp" srcset="img/mock/${d.s}-s.webp 700w, img/mock/${d.s}-m.webp 1100w" sizes="(max-width:700px) 46vw, (max-width:1000px) 46vw, 380px" width="700" height="525" decoding="async" ${k<4?'fetchpriority="high"':'loading="lazy"'} onload="this.classList.add('in')" alt="${d.n} invitation: the printed card and the opening screen on a phone"><span class="play">Try it live</span></button>
  <div class="meta"><div class="row"><h3>${d.n}</h3><span class="tier">${TIERS[d.t]} · <span data-price="${d.t}">${PRICE[cur][d.t]}</span> <s class="twas" data-was="${d.t}">${WAS[cur][d.t]}</s></span></div><p>${d.g}</p>
  <div class="acts"><button data-open="${i}">Try it live</button><button class="order" data-order="${i}">Order</button></div></div></article>`}
const PAGE=10;let shown=PAGE;const moreb=document.getElementById("moreb");
function inOcc(d){return occ==="all"||hasOcc(d,occ)}
function listFor(f){return DESIGNS.map((d,i)=>i).filter(i=>(f==="all"||DESIGNS[i].t===f)&&inOcc(DESIGNS[i]))}
function occHTML(){const o=[["all","All",DESIGNS.length]].concat(Object.keys(OCC).map(k=>[k,OCC[k],DESIGNS.filter(d=>hasOcc(d,k)).length]));return o.map(([k,l,n])=>(OCC_SEP[k]?`<i class="occsep" aria-hidden="true"></i>`:"")+`<button type="button" data-o="${k}" aria-pressed="${occ===k}">${l}<span>${n}</span></button>`).join("")}
function tierOpts(){return [["all","All",DESIGNS.filter(inOcc).length]].concat(Object.keys(TIERS).map(k=>[k,TIERS[k],DESIGNS.filter(d=>d.t===k&&inOcc(d)).length])).filter(x=>x[0]==="all"||x[2]>0)}
function renderGrid(from){const L=listFor(filter),n=Math.min(shown,L.length);from=from||0;
  grid.innerHTML=L.slice(0,n).map((i,k)=>cardHTML(DESIGNS[i],i,k)).join("");
  const lab=filter==="all"?"designs":TIERS[filter]+" designs";
  moreb.innerHTML=(n<L.length?`<button class="btn solid" type="button" data-more>View more</button>`:"")+(L.length>PAGE?`<button class="btn ghost" type="button" data-all>View all · ${L.length}</button><small>Showing ${n} of ${L.length} ${lab}</small>`:"");
  if(window.gsap&&!reduce)gsap.from([...grid.children].slice(from),{y:40,duration:.8,stagger:.06,ease:"power3.out",clearProps:"transform"})}
moreb.addEventListener("click",e=>{if(e.target.closest("[data-more]")){const f=shown;shown+=PAGE;renderGrid(f);if(window.ScrollTrigger)ScrollTrigger.refresh()}else if(e.target.closest("[data-all]"))location.hash="all"+(filter==="all"?"":"/"+filter)});
occsEl.addEventListener("click",e=>{const b=e.target.closest("[data-o]");if(!b)return;occ=b.dataset.o;shown=PAGE;renderFilters();renderGrid();occIntoView(occsEl)});
filters.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;filter=b.dataset.f;shown=PAGE;renderFilters();renderGrid()});
document.querySelectorAll("[data-f]").forEach(a=>{if(a.tagName==="A")a.addEventListener("click",()=>{filter=a.dataset.f;shown=PAGE;renderFilters();renderGrid()})});
function cardClick(e){const g=e.target.closest("[data-pd]");if(g){goDesign(+g.dataset.pd);return}const o=e.target.closest("[data-open]");if(o){openViewer(+o.dataset.open);return}const r=e.target.closest("[data-order]");if(r)goOrder(+r.dataset.order)}
grid.addEventListener("click",cardClick);
renderFilters();renderGrid();


/* ---------- opening wheel ---------- */
(function(){const wheel=document.getElementById("wheel"),ring=document.getElementById("ring");if(!wheel)return;
  const N=DESIGNS.length,STEP=360/N,cards=DESIGNS.map((d,i)=>{const b=document.createElement("button");b.className="wcard";b.type="button";b.setAttribute("aria-label","Open "+d.n);
    b.innerHTML=`<img src="img/wheel/${d.s}.webp" alt="" ${i<5||i>N-4?'fetchpriority="high"':''} decoding="async">`;b.dataset.i=i;ring.appendChild(b);return b});
  let W=0,H=0,R=0,CW=0,cx=0,cy=0,base=0,vel=0,target=null,intro=0,t0=performance.now(),dragging=false,moved=0,lastX=0,lastT=0,idle=true,hot=-1;
  function size(){W=wheel.clientWidth;H=wheel.clientHeight;const mob=W<700;CW=mob?Math.max(90,Math.min(124,W*.29)):Math.min(168,W*.115);
    R=mob?Math.min(W*.86,H*.44):Math.min(W*.36,H*.5);cx=W/2;cy=(mob?H*.47:H*.40)+R;
    wheel.style.setProperty("--cw",CW+"px");wheel.style.setProperty("--r",R+"px");wheel.style.setProperty("--cy",cy+"px")}
  size();addEventListener("resize",size);
  const ease=k=>1-Math.pow(1-k,3);
  window.wRefresh=()=>{const h=hot<0?0:hot;hot=-1;label(h)};
  function label(i){if(i===hot)return;hot=i;cards.forEach((c,j)=>c.classList.toggle("hot",j===i));const d=DESIGNS[i];
    document.getElementById("wName").textContent=d.n;document.getElementById("wTier").innerHTML=TIERS[d.t]+" · "+PRICE[cur][d.t]+' <s class="twas">'+WAS[cur][d.t]+"</s>"}
  function frame(now){
    const k=Math.min(1,(now-t0)/1800);intro=ease(k);
    if(!dragging){if(target!==null){const d=target-base;base+=d*.12;if(Math.abs(d)<.05){base=target;target=null}}else if(Math.abs(vel)>.01){base+=vel;vel*=.94}else if(idle&&k>=1){base-=.045}}
    let best=0,bd=1e9;
    cards.forEach((c,i)=>{let a=((i*STEP+base)%360+540)%360-180;const ai=a*intro,rad=ai*Math.PI/180;const st=c._s||(c._s={});
      const x=cx+R*Math.sin(rad),y=cy-R*Math.cos(rad),vis=Math.abs(a)<(W<700?104:84);
      const near=Math.max(0,1-Math.abs(a)/90),sc=(.72+.36*near)*(.35+.65*intro);
      if(vis||st.v){c.style.transform=`translate3d(${(x-CW/2).toFixed(1)}px,${(y-CW*606/280/2).toFixed(1)}px,0) rotate(${ai.toFixed(2)}deg) scale(${sc.toFixed(3)})`}
      const op=vis?Math.min(1,+(intro*1.4).toFixed(2)):0;if(st.o!==op){c.style.opacity=op;st.o=op}
      const z=Math.round(near*20);if(st.z!==z){c.style.zIndex=z;st.z=z}
      if(st.v!==vis){c.style.pointerEvents=vis?"auto":"none";c.style.visibility=vis?"visible":"hidden";st.v=vis}
      if(Math.abs(a)<bd){bd=Math.abs(a);best=i}});
    if(intro>.6)label(best);requestAnimationFrame(frame)}
  requestAnimationFrame(t=>{t0=t;wheel.classList.add("on");frame(t)});
  function snap(){const a=Math.round(base/STEP)*STEP;target=a}
  ring.addEventListener("pointerdown",e=>{dragging=true;moved=0;lastX=e.clientX;lastT=performance.now();vel=0;target=null;idle=false;wheel.classList.add("used");ring.classList.add("drag");try{ring.setPointerCapture(e.pointerId)}catch(_){}});
  ring.addEventListener("pointermove",e=>{if(!dragging)return;const dx=e.clientX-lastX,now=performance.now();moved+=Math.abs(dx);const deg=dx*(W<700?.32:.16);base+=deg;vel=deg/Math.max(8,now-lastT)*16;lastX=e.clientX;lastT=now});
  const up=e=>{if(!dragging)return;dragging=false;ring.classList.remove("drag");
    if(moved<8){const c=e.target.closest&&e.target.closest(".wcard");if(c){const i=+c.dataset.i;if(i===hot)goDesign(i);else{target=base-((((i*STEP+base)%360+540)%360-180))}}vel=0}
    else{setTimeout(snap,350)}};
  ring.addEventListener("pointerup",up);ring.addEventListener("pointercancel",up);
  document.getElementById("wOpen").addEventListener("click",()=>goDesign(hot));
})();

/* ---------- product page (#d/slug) ---------- */
const FAQ=[
 ["What exactly is a Bulawa card?","A wedding invitation that opens as its own web page. Your guests tap one link on WhatsApp and the card opens with its own opening, music, your names, every function, the venue map and an RSVP button. Nothing to download. It works on every iPhone, Android and laptop.","home,pd"],
 ["How does ordering work?","Pick a design, fill in your names, dates and venues, and see your own card right away. Pay by JazzCash or bank transfer and upload the receipt on the same page. Once we confirm the payment, your card goes live without the watermark and your wedding kit opens.","home,pd"],
 ["How fast will my card be ready?","You see your preview within a minute of filling the form. After payment we confirm and make it live, usually within a few hours. Designs marked for a personal preview arrive on WhatsApp within 24 hours.","home,pd"],
 ["Different guests for different functions?","Yes, and at no extra cost. You get one link with all your events, a link for each event, and any mix you like. For example the Walima link for everyone, Mehndi plus Baraat for relatives, and the full card for close family. Guests only see the events on their link.","home,pd"],
 ["Can I change details after sending the card?","Yes, yourself, any time. Your private kit page has an Edit button: change names, Mr & Mrs, dates, times, venues, map links or the RSVP number, tap Save, and the same link updates for every guest. For a new picture, music or design, message us on WhatsApp.","home,pd"],
 ["How do guests reply?","Every card has a one tap \"we'll be there\" button. It sends a ready message straight to your WhatsApp, so replies don't get lost in family groups.","home,pd"],
 ["Is the card in Urdu too?","Yes. Every card has English and Urdu, and each guest can switch with one tap.","home,pd"],
 ["Can I use my own song?","Yes. Every design comes with music. Send us any song you love and we set the part you like as your card's music.","home,pd"],
 ["What is in the free wedding kit?","With every paid card you get a private kit page: save the date for status and Instagram, a reminder image for each function, a QR standee for the venue, a printable card and PDF, ready messages to send guests, and a guest list and budget planner. The kit link is only for you, not for guests.","home,pd"],
 ["Can you make a design just for us?","Yes. We can match your outfits, your theme or your venue, or make something completely new. Charges depend on the idea, so message us on WhatsApp with your idea and date and we share the exact price.","home"],
 ["I live abroad. Can I still order?","Of course. Prices show in your own currency, and you can pay by PayPal or bank transfer. If you need help, message us on WhatsApp. Time zones are not a problem.","home"]];
function faqHTML(where){return FAQ.filter(f=>f[2].includes(where)).map((f,i)=>`<details${i?"":" open"}><summary>${f[0]}<i></i></summary><p>${f[1]}</p></details>`).join("")}
(function(){const h=document.getElementById("faqHome");if(h)h.innerHTML=faqHTML("home")})();
